public String firstLine(Path path) {
    try (BufferedReader reader = Files.newBufferedReader(path)) {   // closed automatically
        return reader.readLine();
    } catch (NoSuchFileException e) {        // specific first
        return "";                           // a missing file is acceptable here
    } catch (IOException e) {                // then the general case
        throw new UncheckedIOException("Could not read " + path, e);   // keep the cause
    }
}

